<template>
  <div class="state-msg" :role="tone === 'error' ? 'alert' : 'status'" :aria-busy="loading ? 'true' : 'false'">
    <div class="state-badge" :class="`state-badge--${tone}`">
      <span v-if="loading" class="dw-spinner state-spinner" aria-hidden="true" />
      <v-icon v-else :icon="icon" size="32" />
    </div>
    <div class="state-title">{{ title }}</div>
    <div v-if="message" class="state-text">{{ message }}</div>
    <button v-if="actionLabel" type="button" class="btn-primary state-btn" @click="$emit('action')">
      {{ actionLabel }}
    </button>
  </div>
</template>

<script>
// Shared loading / empty / error state used by every tab (FR-23).
export default {
  name: "StateMessage",
  props: {
    icon: { type: String, default: "mdi-file-search-outline" },
    title: { type: String, required: true },
    message: { type: String, default: "" },
    actionLabel: { type: String, default: "" },
    // neutral | error | info — replaces ad-hoc colour props
    tone: { type: String, default: "neutral" },
    loading: { type: Boolean, default: false },
    // kept for backwards compatibility with existing callers; colours come from the tone
    iconColor: { type: String, default: "" },
    badgeColor: { type: String, default: "" },
    actionColor: { type: String, default: "" },
  },
  emits: ["action"],
};
</script>

<style scoped>
.state-msg {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 48px 20px;
  gap: 6px;
}
.state-badge {
  width: 64px;
  height: 64px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: var(--dw-surface-muted);
  color: var(--dw-text-subtle);
  margin-bottom: var(--dw-sp-2);
}
.state-badge--error {
  background: var(--dw-error-soft);
  color: var(--dw-error);
}
.state-badge--info {
  background: var(--dw-primary-soft);
  color: var(--dw-primary);
}
.state-spinner {
  width: 26px;
  height: 26px;
  border-width: 3px;
  color: var(--dw-primary);
}
.state-title {
  font-size: var(--dw-fs-md);
  font-weight: var(--dw-fw-semibold);
  color: var(--dw-text);
}
.state-text {
  font-size: var(--dw-fs-base);
  color: var(--dw-text-muted);
  max-width: 380px;
}
.state-btn {
  margin-top: var(--dw-sp-3);
}
@media (max-width: 480px) {
  .state-msg {
    padding: 32px 12px;
  }
}
</style>
