import { COLORS, PALETTE, MONTHS } from "./dashboardData";

const STATUS_STYLE = {
  Active: { icon: "mdi-check-circle-outline", color: COLORS.green },
  "On Hold": { icon: "mdi-pause-circle-outline", color: COLORS.orange },
  Expired: { icon: "mdi-clock-alert-outline", color: COLORS.red },
  Archived: { icon: "mdi-archive-outline", color: COLORS.purple },
};

const titleCase = (s = "") => s.charAt(0).toUpperCase() + s.slice(1).toLowerCase();

// one readable state per project
const stateOf = (p) =>
  p.archived ? "Archived" : p.onHold ? "On Hold" : p.expired ? "Expired" : titleCase(p.status);

const monthOf = (iso) => (iso ? iso.slice(0, 7).replace("-", "/") : ""); // "2026/09"
const monthLabel = (key) => MONTHS[parseInt(key.split("/")[1], 10) - 1];

const countBy = (rows, fn) => {
  const m = new Map();
  rows.forEach((r) => {
    const k = fn(r);
    if (k) m.set(k, (m.get(k) || 0) + 1);
  });
  return [...m.entries()];
};
const pct = (v, total) => (total ? Math.round((v / total) * 1000) / 10 : 0);

// Projects API -> same shape as mapFederatedResponse, so charts/KPIs/drill-down work unchanged
export function mapExternalProjects(list) {
  const results = list.map((p) => ({
    resourceid: p.id,
    key: p.key,
    title: p.name,
    name: p.key,
    objType: titleCase(p.type), // Scrum / Kanban
    owner: p.lead?.displayName || "",
    description: p.description || "",
    state: stateOf(p),
    originated: p.createdAt,
    estimatedStartDate: p.startDate,
    estimatedFinishDate: p.endDate,
    dueDate: p.endDate,
    delayed: p.expired ? "Yes" : "No",
    createdMonth: monthOf(p.createdAt),
  }));
  const total = results.length;

  const kpis = countBy(results, (r) => r.state)
    .map(([raw, value], i) => {
      const s = STATUS_STYLE[raw] || { icon: "mdi-shape-outline", color: PALETTE[i % PALETTE.length] };
      return { label: raw, raw, value, pct: pct(value, total), icon: s.icon, color: s.color };
    })
    .sort((a, b) => b.value - a.value);

  const months = countBy(results, (r) => r.createdMonth).sort((a, b) => a[0].localeCompare(b[0]));

  const owners = countBy(results, (r) => r.owner)
    .map(([name, value]) => ({ name, raw: name, value }))
    .sort((a, b) => b.value - a.value)
    .slice(0, 10);

  // the "Policy" donut shows the project type (Scrum / Kanban)
  const policies = countBy(results, (r) => r.objType).map(([label, value], i) => ({
    label, raw: label, value, pct: pct(value, total), color: PALETTE[i % PALETTE.length],
  }));

  return {
    total,
    kpis,
    line: months.map(([, v]) => v),
    lineCategories: months.map(([k]) => monthLabel(k)),
    lineRaw: months.map(([k]) => k),
    owners,
    policies,
    results,
    createdMonths: months.map(([k, v]) => ({ label: `${monthLabel(k)} (${v})`, raw: k })),
    modifiedMonths: [],
    collaborativeSpaces: [],
    lastModifiedByUsers: [],
    facets: [],
  };
}

// External drill-down is local: a clicked chart value (status, owner, month, type)
export function matchesDrill(row, raw) {
  return [row.state, row.owner, row.createdMonth, row.objType].includes(raw);
}
