<template>
  <DwDialog
    :model-value="modelValue"
    :title="text.title"
    :subtitle="step === 1 ? 'Step 1 of 2 · Choose a chart type' : 'Step 2 of 2 · Choose the attribute to group by'"
    icon="mdi-chart-box-plus-outline"
    max-width="460"
    @update:model-value="$emit('update:modelValue', $event)"
  >
    <template v-if="step === 1">
      <div class="type-grid" role="radiogroup" :aria-label="text.chartTypeLabel">
        <button
          v-for="ct in chartTypes"
          :key="ct.value"
          type="button"
          role="radio"
          class="type-card"
          :class="{ active: form.chartType === ct.value }"
          :aria-checked="form.chartType === ct.value ? 'true' : 'false'"
          @click="form.chartType = ct.value"
        >
          <v-icon :icon="ct.icon" size="22" />
          <span>{{ ct.label }}</span>
        </button>
      </div>
    </template>
    <div v-else class="dw-field">
      <label class="dw-label" for="ac-attr">{{ isSingleAttr ? text.attributeLabel : text.xAxisLabel }} <span class="dw-required">*</span></label>
      <v-select id="ac-attr" v-model="form.xAttr" :items="filteredAttrs" hide-details placeholder="Select an attribute" />
    </div>

    <template #footer>
      <button v-if="step === 2" type="button" class="btn-ghost" @click="step = 1">{{ text.back }}</button>
      <span class="dw-spacer" />
      <button type="button" class="btn-outline" @click="$emit('update:modelValue', false)">Cancel</button>
      <button v-if="step === 1" type="button" class="btn-primary" @click="step = 2">{{ text.next }}</button>
      <button v-else type="button" class="btn-primary" :disabled="!form.xAttr" @click="submit">{{ text.submit }}</button>
    </template>
  </DwDialog>
</template>

<script>
import { ATTRIBUTES, CHART_TYPE_OPTIONS, ADD_CHART_DEFAULT_FORM } from "@/utils/dashboardData";
import { ADD_CHART_TEXT } from "@/utils/uiText";
import DwDialog from "@/components/common/DwDialog.vue";

export default {
  name: "AddChartDialog",
  components: { DwDialog },
  props: { modelValue: { type: Boolean, default: false } },
  emits: ["update:modelValue", "add"],

  data() {
    return {
      text: ADD_CHART_TEXT,
      step: 1,
      search: "",
      attributes: ATTRIBUTES,
      form: { ...ADD_CHART_DEFAULT_FORM },
      chartTypes: CHART_TYPE_OPTIONS,
    };
  },

  computed: {
    isSingleAttr() {
      return this.form.chartType === "donut";
    },
    filteredAttrs() {
      const q = this.search.trim().toLowerCase();
      return q
        ? this.attributes.filter((a) => a.toLowerCase().includes(q))
        : this.attributes;
    },
    yAttrOptions() {
      return this.attributes.filter((a) => a !== this.form.xAttr);
    },
  },

  watch: {
    modelValue(v) {
      if (v) {
        this.step = 1;
        this.form = { ...ADD_CHART_DEFAULT_FORM };
      }
    },
  },

  methods: {
    submit() {
      this.$emit("add", { ...this.form });
      this.$emit("update:modelValue", false);
    },
  },
};
</script>

<style scoped>
.type-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(110px, 1fr));
  gap: var(--dw-sp-2);
}
.type-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  padding: var(--dw-sp-3) var(--dw-sp-2);
  border: 1px solid var(--dw-border);
  border-radius: var(--dw-radius);
  background: var(--dw-surface);
  color: var(--dw-text-2);
  font-family: inherit;
  font-size: var(--dw-fs-sm);
  cursor: pointer;
}
.type-card:hover {
  border-color: var(--dw-primary);
}
.type-card.active {
  border-color: var(--dw-primary);
  background: var(--dw-primary-soft);
  color: var(--dw-primary);
  font-weight: var(--dw-fw-semibold);
}
</style>
