<template>
  <div class="tl-wrap">
    <div ref="scroller" class="tl-scroll">
      <div class="tl">
        <div class="tl-head">
          <div class="tl-label">{{ text.name }}</div>
          <div class="tl-area" :style="areaStyle">
            <span v-for="k in ticks" :key="k.pos" class="tl-tick" :class="{ 'tl-tick--m': k.month }"
              :style="{ left: k.pos + '%' }">{{ k.label }}</span>
          </div>
        </div>

        <div v-for="it in items" :key="it.r.id" class="tl-row">
          <div class="tl-label" :title="it.r.title">
            <div class="tl-name">{{ it.r.title }}</div>
            <div class="tl-sub">{{ it.r.objType }}</div>
          </div>
          <div class="tl-area" :style="areaStyle">
            <span v-for="k in ticks" :key="k.pos" class="tl-grid" :class="{ 'tl-grid--m': k.month }"
              :style="{ left: k.pos + '%' }" />
            <span v-if="todayPos != null" class="tl-today" :style="{ left: todayPos + '%' }" />
            <span v-if="it.plan" class="tl-plan" :style="it.plan" :title="it.planTitle" />
            <span v-if="it.act" class="tl-act" :style="it.act" :title="it.actTitle" />
          </div>
        </div>
      </div>
    </div>

    <div class="tl-legend">
      <span><i class="tl-key tl-key--plan" />{{ text.planned }}</span>
      <span v-for="l in legend" :key="l.label"><i class="tl-key" :style="{ background: l.c }" />{{ l.label }}</span>
      <button class="tl-jump" @click="focusToday"><i class="tl-key tl-key--today" />{{ text.today }}</button>
    </div>
  </div>
</template>

<script>
import { SCHEDULE_TEXT } from "@/utils/uiText";
import { SCHEDULE_HEALTH_COLORS as C } from "@/utils/dashboardData";

const DAY = 86400000;
const WEEK = 7 * DAY;
const WEEK_PX = 56; // width of one week column
const LABEL_PX = 260;

const ms = (v) => {
  const t = v ? new Date(v).getTime() : NaN;
  return isNaN(t) ? null : t;
};
const fmt = (v) => (v == null ? "–" : new Date(v).toLocaleDateString());
const monday = (t) => {
  const d = new Date(t);
  d.setHours(0, 0, 0, 0);
  d.setDate(d.getDate() - ((d.getDay() + 6) % 7));
  return d.getTime();
};

export default {
  name: "ScheduleTimeline",
  props: {
    rows: { type: Array, required: true }, // rows drawn (current page)
    rangeRows: { type: Array, default: null }, // rows that decide the axis range (all matches)
  },
  data: () => ({ text: SCHEDULE_TEXT }),
  computed: {
    legend() {
      return [
        { label: this.text.onTime, c: C.onTime },
        { label: this.text.late, c: C.late },
        { label: this.text.overdue, c: C.overdue },
        { label: this.text.open, c: C.open },
      ];
    },
    bounds() {
      const vals = [Date.now()];
      (this.rangeRows || this.rows).forEach((r) => {
        const s = this.span(r);
        [s.ps, s.pe, s.as, s.ae].forEach((v) => v != null && vals.push(v));
      });
      return {
        lo: monday(Math.min(...vals)) - WEEK,
        hi: monday(Math.max(...vals)) + 2 * WEEK,
      };
    },
    px() {
      const { lo, hi } = this.bounds;
      return Math.round((hi - lo) / WEEK) * WEEK_PX;
    },
    areaStyle() {
      return { width: this.px + "px", flex: `0 0 ${this.px}px` };
    },
    todayPos() {
      const p = this.pos(Date.now());
      return p >= 0 && p <= 100 ? p : null;
    },
    ticks() {
      const { lo, hi } = this.bounds;
      const list = [];
      const d = new Date(lo);
      while (d.getTime() <= hi) {
        list.push({
          pos: this.pos(d.getTime()),
          label: d.toLocaleDateString(undefined, { day: "numeric", month: "short" }),
          month: d.getDate() <= 7, // first week of a month
        });
        d.setDate(d.getDate() + 7);
      }
      return list;
    },
    items() {
      const today = new Date().setHours(0, 0, 0, 0);
      return this.rows.map((r) => {
        const s = this.span(r);
        const actEnd = s.ae ?? (s.as != null ? Math.max(today, s.as) : null);
        let color = C.open;
        if (s.ae != null) color = s.pe != null && s.ae > s.pe ? C.late : C.onTime;
        else if (s.pe != null && s.pe < today) color = C.overdue;

        const act = this.bar(s.as, actEnd);
        return {
          r,
          plan: this.bar(s.ps, s.pe),
          planTitle: `${this.text.planned}: ${fmt(s.ps)} → ${fmt(s.pe)}`,
          act: act && { ...act, background: color },
          actTitle: `${fmt(s.as)} → ${fmt(s.ae)}`,
        };
      });
    },
  },
  watch: {
    px() {
      this.$nextTick(this.focusToday); // axis range changed
    },
  },
  mounted() {
    this.$nextTick(this.focusToday);
  },
  methods: {
    span(r) {
      return {
        ps: ms(r.estimatedStartDate),
        pe: ms(r.estimatedFinishDate) ?? ms(r.dueDate),
        as: ms(r.actualStartDate),
        ae: ms(r.actualFinishDate),
      };
    },
    pos(v) {
      const { lo, hi } = this.bounds;
      return ((v - lo) / (hi - lo)) * 100;
    },
    bar(a, b) {
      if (a == null && b == null) return null;
      a = a ?? b;
      b = Math.max(b ?? a, a);
      return { left: this.pos(a) + "%", width: Math.max(this.pos(b + DAY) - this.pos(a), 0.2) + "%" };
    },
    focusToday() {
      const el = this.$refs.scroller;
      if (!el) return;
      const x = this.todayPos != null ? (this.todayPos / 100) * this.px : 0;
      el.scrollLeft = Math.max(0, x - (el.clientWidth - LABEL_PX) / 2);
    },
  },
};
</script>

<style scoped>
