}

.tl-act {
  top: 24px;
  z-index: 1;
}

.tl-legend {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px 18px;
  padding: 10px 14px;
  font-size: var(--dw-fs-sm);
  color: var(--dw-text-muted);
  background: var(--dw-surface-alt);
  border-top: 1px solid var(--dw-border);
}

.tl-legend span,
.tl-jump {
