}

.tl-jump {
  border: 0;
  background: transparent;
  color: var(--dw-primary);
  font: inherit;
  font-weight: var(--dw-fw-semibold);
  cursor: pointer;
  padding: 0;
}

.tl-key {
  width: 12px;
  height: 8px;
  border-radius: 3px;
  display: inline-block;
}

.tl-key--plan {
  background: var(--dw-primary-border);
}

