<template>
  <DwDialog
    :model-value="modelValue"
    title="Share dashboard"
    :subtitle="dashboard?.name || ''"
    icon="mdi-share-variant-outline"
    :busy="busy"
    max-width="560"
    @update:model-value="$emit('update:modelValue', $event)"
  >
    <div v-if="!checkingRights && !canManage" class="dw-alert" role="status">
      <v-icon icon="mdi-lock-outline" size="18" />
      <span>Only the owner can share this dashboard.</span>
    </div>

    <template v-else>
      <div class="dw-field">
        <label class="dw-label" for="share-people">Share with</label>
        <v-autocomplete
          id="share-people"
          v-model="selected"
          v-model:search="query"
          :items="results"
          :loading="searching"
          item-title="name"
          item-value="id"
          return-object
          multiple
          chips
          closable-chips
          hide-no-data
          no-filter
          prepend-inner-icon="mdi-account-search-outline"
          placeholder="Type at least 2 letters of a name or username"
          hide-details="auto"
          :error-messages="addError"
          :disabled="busy || checkingRights"
        >
          <template #item="{ props, item }">
            <v-list-item v-bind="props" :subtitle="rawOf(item).login" :disabled="isGranted(rawOf(item))">
              <template #prepend>
                <span class="share-avatar share-avatar--sm">{{ initials(rawOf(item).name || rawOf(item).login) }}</span>
              </template>
              <template v-if="isGranted(rawOf(item))" #append><span class="dw-caption">Already shared</span></template>
            </v-list-item>
          </template>
        </v-autocomplete>
        <span class="dw-hint share-hint">
          <v-icon icon="mdi-eye-outline" size="14" />
          They can open it and save their own copy. Only you can change or share it.
        </span>
      </div>
    </template>

    <div class="dw-field">
      <div class="share-list-head">
        <span class="dw-label">Shared with</span>
        <span class="dw-count">{{ people.length }}</span>
      </div>
      <div class="share-list" :aria-busy="loadingGrantees ? 'true' : 'false'">
        <div class="share-row share-row--owner">
          <span class="share-avatar">{{ initials(ownerLabel) }}</span>
          <div class="share-row__text">
            <div class="share-row__name">{{ ownerLabel }}</div>
          </div>
          <span class="dw-badge dw-badge--primary">Owner</span>
        </div>
        <div v-if="loadingGrantees" class="share-row">
          <span class="dw-spinner" aria-hidden="true" /><span class="dw-caption">Loading who it's shared with…</span>
        </div>
        <div v-else-if="!people.length" class="share-row share-row--empty">
          <v-icon icon="mdi-account-multiple-outline" size="18" />
          <span class="dw-caption">Not shared with anyone yet.</span>
        </div>
        <div v-for="g in people" :key="g.id" class="share-row">
          <span class="share-avatar">{{ initials(g.name || g.login) }}</span>
          <div class="share-row__text">
            <div class="share-row__name" :title="g.name || g.login">{{ g.name || g.login }}</div>
            <div v-if="g.login && g.name" class="dw-caption">{{ g.login }}</div>
          </div>
          <span v-if="g.inherited" class="dw-badge" title="Given through another object; it can't be removed here">Inherited</span>
          <button
            v-else-if="canManage"
            type="button"
            class="btn-ghost btn-sm share-remove"
            :aria-label="`Stop sharing with ${g.name || g.login}`"
            :disabled="busy"
            @click="revoke(g)"
          >
            <v-icon icon="mdi-close" /> Remove
          </button>
        </div>
      </div>
    </div>

    <div v-if="error" class="dw-alert dw-alert--error" role="alert">
      <v-icon icon="mdi-alert-circle-outline" size="18" /><span>{{ error }}</span>
    </div>

    <template #footer>
      <button type="button" class="btn-outline" :disabled="busy" @click="$emit('update:modelValue', false)">Close</button>
      <button
        v-if="canManage"
        type="button"
        class="btn-primary"
        :class="{ 'btn-busy': busy }"
        :disabled="busy || !selected.length"
        @click="share"
      >
        <span v-if="busy" class="dw-spinner" aria-hidden="true" />
        <v-icon v-else icon="mdi-send-outline" />
        {{ shareLabel }}
      </button>
    </template>
  </DwDialog>
</template>

<script>
import DwDialog from "@/components/common/DwDialog.vue";
import sharingApi from "@/services/sharingApi";
import peopleApi from "@/services/peopleApi";
import { SHARING } from "@/config/platformConfig";
import { userMessage } from "@/services/apiError";
import { toastBus } from "@/components/common/toastBus";
import { ERROR_TEXT } from "@/utils/uiText";
import { useDashboardStore } from "@/store/dashboardStore";
import { isOwnedByCurrentUser } from "@/services/dashboardDocumentApi";

const key = (x) => String(x || "").trim().toLowerCase();

// Share dialog. Only the owner can share; everyone it is shared with gets the same access
// (SHARING.shareLevel): open the dashboard and save their own copy. Success is reported
// only after the platform confirms.
export default {
  name: "ShareDialog",
  components: { DwDialog },
  props: {
    modelValue: Boolean,
    dashboard: { type: Object, default: null }, // { id, name, owner, ownerName, access }
  },
  emits: ["update:modelValue", "changed"],
  data() {
    return {
      canManage: false,
      checkingRights: false,
      query: "",
      results: [],
      selected: [],
      searching: false,
      grantees: [],
      loadingGrantees: false,
      busy: false,
      error: "",
      addError: "",
      searchTimer: null,
      searchSeq: 0,
    };
  },
  computed: {
    isOwner() {
      return this.dashboard?.access === "owner" || isOwnedByCurrentUser(this.dashboard?.owner);
    },
    ownerLabel() {
      const name = this.dashboard?.ownerName || this.dashboard?.owner || "Owner";
      return this.isOwner ? `${name} (you)` : name;
    },
    // Everyone listed by the platform except the owner, who is shown on the first row.
    people() {
      return this.grantees.filter((g) => g.level !== "Owner" && key(g.login) !== key(this.dashboard?.owner));
    },
    shareLabel() {
      if (this.busy) return "Sharing…";
      const n = this.selected.length;
      return n > 1 ? `Share with ${n} people` : "Share";
    },
  },
  watch: {
    modelValue(open) {
      if (open) this.reset();
    },
    query(text) {
      clearTimeout(this.searchTimer);
      this.searchTimer = setTimeout(() => this.search(text), 300);
    },
  },
  beforeUnmount() {
    clearTimeout(this.searchTimer);
  },
  methods: {
    initials(s) {
      return String(s || "?").split(/[\s.]+/).filter(Boolean).map((p) => p[0]).slice(0, 2).join("").toUpperCase();
    },
    // Vuetify passes either a wrapped list item ({ raw }) or the object itself.
    rawOf(item) {
      return item?.raw ?? item ?? {};
    },
    isGranted(p) {
      const me = useDashboardStore().user?.login;
      return (
        key(p.login) === key(this.dashboard?.owner) ||
        (!!me && key(p.login) === key(me)) ||
        this.grantees.some((g) => (p.personId && key(g.personId) === key(p.personId)) || (p.login && key(g.login) === key(p.login)))
      );
    },
    async reset() {
      Object.assign(this, { query: "", results: [], selected: [], error: "", addError: "", canManage: false });
      await Promise.all([this.loadRights(), this.loadGrantees()]);
    },
    // Only the owner shares, and only when the platform also allows it.
    async loadRights() {
      this.checkingRights = true;
      try {
        this.canManage = this.isOwner && (await sharingApi.canShare(this.dashboard.id).catch(() => false));
      } finally {
        this.checkingRights = false;
      }
    },
    async loadGrantees() {
      this.loadingGrantees = true;
      try {
        this.grantees = await sharingApi.listGrantees(this.dashboard.id);
      } catch (e) {
        this.error = userMessage(e, ERROR_TEXT.loadAccess);
      } finally {
        this.loadingGrantees = false;
      }
    },
    async search(text) {
      const seq = ++this.searchSeq;
      this.addError = "";
      if (!text || text.trim().length < 2) {
        this.results = [...this.selected];
        return;
      }
      this.searching = true;
      try {
        const found = await peopleApi.search(text);
        if (seq === this.searchSeq) this.results = [...this.selected, ...found.filter((f) => !this.selected.some((s) => s.id === f.id))];
      } catch (e) {
        if (seq === this.searchSeq) this.addError = userMessage(e, ERROR_TEXT.searchPeople);
      } finally {
        if (seq === this.searchSeq) this.searching = false;
      }
    },
    validate() {
      const ids = new Set();
      for (const p of this.selected) {
        if (ids.has(p.id)) return "The same person is selected twice.";
        ids.add(p.id);
        if (this.isGranted(p)) return `It's already shared with ${p.name || p.login}.`;
        if (!p.personId) return `${p.name || "This person"} can't be identified on the platform.`;
      }
      return "";
    },
    async share() {
      this.error = "";
      this.addError = this.validate();
      if (this.addError) return;
      this.busy = true;
      try {
        await sharingApi.grant(this.dashboard.id, this.selected, SHARING.shareLevel);
        const n = this.selected.length;
        toastBus.emit(n === 1 ? `Shared with ${this.selected[0].name || this.selected[0].login}.` : `Shared with ${n} people.`, "success");
        this.selected = [];
        this.results = [];
        await this.loadGrantees();
        this.$emit("changed");
      } catch (e) {
        this.error = userMessage(e, ERROR_TEXT.share);
      } finally {
        this.busy = false;
      }
    },
    async revoke(g) {
      this.busy = true;
      this.error = "";
      try {
        await sharingApi.revoke(this.dashboard.id, g);
        await this.loadGrantees();
        toastBus.emit(`Stopped sharing with ${g.name || g.login}.`, "success");
        this.$emit("changed");
      } catch (e) {
        this.error = userMessage(e, ERROR_TEXT.removeAccess);
      } finally {
        this.busy = false;
      }
    },
  },
};
</script>

<style scoped>
.share-hint {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-top: var(--dw-sp-1);
}
.share-list-head {
  display: flex;
  align-items: center;
  gap: var(--dw-sp-2);
}
.share-list {
  border: 1px solid var(--dw-border);
  border-radius: var(--dw-radius);
  max-height: 260px;
  overflow-y: auto;
}
.share-row {
  display: flex;
  align-items: center;
  gap: var(--dw-sp-3);
  min-height: 48px;
  padding: var(--dw-sp-2) var(--dw-sp-3);
  border-top: 1px solid var(--dw-divider);
}
.share-row:first-child {
  border-top: 0;
}
.share-row--owner {
  background: var(--dw-surface-alt);
}
.share-row--empty {
  color: var(--dw-text-subtle);
}
.share-row__text {
  flex: 1;
  min-width: 0;
}
.share-row__name {
  font-weight: var(--dw-fw-semibold);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.share-remove {
  flex-shrink: 0;
}
.share-avatar {
  width: 30px;
  height: 30px;
  border-radius: 50%;
  background: var(--dw-primary-soft);
  color: var(--dw-primary);
  font-size: var(--dw-fs-xs);
  font-weight: var(--dw-fw-bold);
  display: grid;
  place-items: center;
  flex-shrink: 0;
}
.share-avatar--sm {
  width: 24px;
  height: 24px;
  margin-right: var(--dw-sp-2);
}
</style>
