import http from "./httpClient.js";
import dashboardApi from "./dashboardApi.js";
import { useDashboardStore } from "@/store/dashboardStore.js";
import { SCHEDULE_TYPES } from "@/utils/dashboardData";
import { PROJECT_SCOPE } from "@/config/platformConfig";
import { identityOf } from "@/services/activityApi";
import { allValues, escapeQueryValue, firstText, firstValue } from "@/utils/searchResult";

const SEARCH = "/federated/search";
const TYPE_KEY = "ds6w:what/ds6w:type";
const USED_IN_PROJECT = "ds6w:where/ds6w:context/ds6w:usedInProject";
const PAGE = 40;
const MAX_PAGES = 5000; // safety stop per search
const DETAIL_PARALLEL = 16; // detail calls in flight at once
const FLUSH_EVERY = 5; // rows handed to the UI per update
const LABEL_FIELDS = ["ds6w:label", "dcterms:title", "ds6w:identifier"];

const labelOf = (r) =>
  LABEL_FIELDS.map((f) => firstText(r, f)).find(Boolean) ||
  String(r.label || r.title || r.name || "");

function baseCfg(type) {
  const e = useDashboardStore().getTypeConfig.find((t) => t.name === type);
  return {
    query: e?.query || "(3dexpprd:#all)",
    refine: e?.refineValue ? dashboardApi.refineOf(TYPE_KEY, e.refineValue) : {},
  };
}

// pages through a search; onPage(batch, json) hands each page over as it arrives; max stops early
async function searchAll(type, { query, refine, size = PAGE, predicates = [], source, onPage, max }) {
  const all = [];
  let next = null;
  for (let page = 0; page < MAX_PAGES; page++) {
    const p = dashboardApi.buildPayload(type, refine, size, next, query);
    p.query = query;
    p.refine = refine;
    p.select_predicate = [...new Set([...(p.select_predicate || []), ...predicates])];
    if (source) p.source = source;
    if (!next) p.start = "0";
    let json;
    try {
      json = await http.post(SEARCH, p);
    } catch (e) {
      if (!all.length) throw e;
      all.truncated = true; // the search refused to go deeper; keep what was read
      break;
    }
    const batch = json.results || [];
    all.push(...batch);
    onPage?.(batch, json);
    if (max && all.length >= max) return all.slice(0, max);
    next = json.infos?.next_start;
    if (batch.length < size || !next) break;
  }
  return all;
}

async function mapLimit(items, limit, fn) {
  const out = new Array(items.length);
  let i = 0;
  const worker = async () => {
    while (i < items.length) {
      const k = i++;
      out[k] = await fn(items[k]);
    }
  };
  await Promise.all(Array.from({ length: Math.min(limit, items.length) }, worker));
  return out;
}

const WORK_OPTS = {
  predicates: [USED_IN_PROJECT, "resourceid", "ds6w:when/ds6w:modified", ...LABEL_FIELDS],
  source: ["3dspace", "swym"],
};

// all results of one work type (Task / Milestone / Phase / Gate) in one project
async function findByType(projectName, subType) {
  const typeRefine = dashboardApi.refineOf(TYPE_KEY, subType);
  const found = await searchAll("Task", {
    ...WORK_OPTS,
    query: baseCfg("Task").query,
    refine: { ...typeRefine, ...dashboardApi.refineOf(USED_IN_PROJECT, projectName) },
  });
  if (found.length) return found;

  // fallback: text search on the project name, keep exact matches only
  const q = `"${projectName.replace(/"/g, '\\"')}"`;
  const byText = await searchAll("Task", { ...WORK_OPTS, query: q, refine: typeRefine });
  return byText.filter((r) => allValues(r, USED_IN_PROJECT).includes(projectName));
}

// Work items of several projects with one search per work type: the project names are
// sent as alternative values of the project facet. Returns Map(projectName -> rows); an
// item used in two of the projects is listed under each. Only items whose project facet
// names one of the given projects are kept.
async function tasksOfProjectGroup(names) {
  const wanted = new Set(names);
  const out = new Map();
  for (const t of SCHEDULE_TYPES) {
    const found = await searchAll("Task", {
      ...WORK_OPTS,
      size: PROJECT_SCOPE.taskPageSize,
      query: baseCfg("Task").query,
      refine: { ...dashboardApi.refineOf(TYPE_KEY, t), ...dashboardApi.refineOf(USED_IN_PROJECT, names) },
    });
    found.forEach((r) => {
      const row = lightRow(r, t);
      if (!row.id) return;
      new Set(allValues(r, USED_IN_PROJECT).map(String)).forEach((name) => {
        if (!wanted.has(name)) return;
        if (!out.has(name)) out.set(name, []);
        out.get(name).push({ ...row, project: name });
      });
    });
  }
  return out;
}

// estimatedDuration is read as days (calendar days); a milestone with 0 finishes on its start date
const durationDays = (v) => parseFloat(v);
function addDays(start, days) {
  const t = new Date(start);
  if (!start || isNaN(t) || !isFinite(days)) return undefined;
  t.setDate(t.getDate() + Math.max(0, Math.ceil(days) - 1));
  return t.toISOString();
}

// a row from a search result only (no dates yet)
const lightRow = (r, subType) => ({
  id: firstValue(r, "resourceid"),
  title: labelOf(r),
  name: firstValue(r, "ds6w:identifier"),
  objType: subType,
  project: firstText(r, USED_IN_PROJECT),
  state: firstText(r, "ds6w:what/ds6w:status").split(".").pop(),
  modified: firstText(r, "ds6w:when/ds6w:modified"),
  detailed: false,
});

async function fetchDetail(id) {
  try {
    return (await http.get(`/resources/v1/modeler/tasks/${id}`))?.data?.[0]?.dataelements || {};
  } catch (e) {
    return {}; // keep the row; its dates stay empty
  }
}

const withDates = (base, d) => ({
  ...base,
  detailed: true,
  state: d.state || base.state,
  estimatedStartDate: d.estimatedStartDate,
  estimatedFinishDate:
    d.estimatedFinishDate || addDays(d.estimatedStartDate, durationDays(d.estimatedDuration)),
  dueDate: d.dueDate,
  actualStartDate: d.actualStartDate,
  actualFinishDate: d.actualFinishDate,
});

// dates already read are kept in the browser, keyed by task id + last-modified, so the next visit
// shows every count at once and only changed tasks are read again
const CACHE_BASE = "schedule-dates-v2";
const cacheKey = () => `${CACHE_BASE}|${useDashboardStore().cacheScope}`;
const DATE_KEYS = ["state", "estimatedStartDate", "estimatedFinishDate", "dueDate", "actualStartDate", "actualFinishDate"];
let cache = null;
let cacheFor = null;
const getCache = () => {
  const key = cacheKey();
  if (cache && cacheFor === key) return cache;
  cacheFor = key;
  try {
    cache = JSON.parse(localStorage.getItem(key) || "{}");
  } catch (e) {
    cache = {};
  }
  return cache;
};
let saveTimer = null;
const saveCache = () => {
  if (saveTimer) return; // at most one write every 2 s, also during a long scan
  saveTimer = setTimeout(() => {
    saveTimer = null;
    try {
      localStorage.setItem(cacheKey(), JSON.stringify(getCache()));
    } catch (e) {
      cache = {}; // storage full or unavailable: carry on without it
    }
  }, 2000);
};
const fromCache = (base) => {
  const c = base.modified && getCache()[base.id];
  return c && c.m === base.modified ? { ...base, detailed: true, ...c.d } : null;
};
const toCache = (row) => {
  if (!row.modified || !(row.estimatedStartDate || row.estimatedFinishDate || row.dueDate)) return; // a failed read is not kept
  getCache()[row.id] = { m: row.modified, d: Object.fromEntries(DATE_KEYS.map((k) => [k, row[k]])) };
  saveCache();
};

// loads the date details of the given rows; reports finished rows in groups of `flushEvery`
async function loadDetails(rows, onRows, flushEvery = FLUSH_EVERY) {
  const done = [];
  let buf = [];
  const flush = () => {
    if (buf.length) {
      onRows?.(buf);
      buf = [];
    }
  };
  await mapLimit(rows, DETAIL_PARALLEL, async (base) => {
    let row = fromCache(base);
    if (!row) {
      row = withDates(base, await fetchDetail(base.id));
      toCache(row);
    }
    done.push(row);
    buf.push(row);
    if (buf.length >= flushEvery) flush();
  });
  flush();
  saveCache();
  return done;
}

// ---- projects assigned to the current user ----
const lc = (v) => String(v || "").trim().toLowerCase();
const ASSIGNED_TTL = 5 * 60 * 1000;
let assignedMemo = null; // { key, at, promise }

// Project names listed on the current user's own Person object (project membership).
async function memberProjectNames() {
  const login = String(useDashboardStore().getUser?.login || "").trim();
  if (!login) return [];
  const rows = await searchAll("Person", {
    query: `[ds6w:type]:"Person" AND [ds6w:identifier]:"${escapeQueryValue(login)}"`,
    refine: {},
    size: 10,
    max: 10,
    predicates: ["resourceid", "ds6w:identifier", PROJECT_SCOPE.memberPredicate],
    source: ["3dspace"],
  });
  // only the signed-in user's own Person object counts (exact username match)
  const mine = rows.filter((r) => lc(firstValue(r, "ds6w:identifier")) === lc(login));
  return [...new Set(mine.flatMap((r) => allValues(r, PROJECT_SCOPE.memberPredicate).map(String)).filter(Boolean))];
}

// Adds to `into` the names that are Project Spaces the user can see (with their ids).
async function addProjectsNamed(names, into) {
  const cfg = baseCfg("Project");
  for (let i = 0; i < names.length; i += PROJECT_SCOPE.nameChunk) {
    const part = names.slice(i, i + PROJECT_SCOPE.nameChunk);
    const wanted = new Set(part);
    const byLabel = part.map((n) => `[ds6w:label]:"${escapeQueryValue(n)}"`).join(" OR ");
    await searchAll("Project", {
      query: `${cfg.query} AND (${byLabel})`,
      refine: cfg.refine,
      predicates: [...LABEL_FIELDS, "resourceid"],
      onPage: (rows) =>
        rows.forEach((r) => {
          const name = labelOf(r);
          if (wanted.has(name) && !into.has(name)) into.set(name, { name, id: firstValue(r, "resourceid") });
        }),
    });
  }
}

// Adds to `into` the Project Spaces whose PROJECT_SCOPE.predicate matches the user (owned).
async function addOwnedProjects(ids, into) {
  const who = ids.map((v) => `[${PROJECT_SCOPE.predicate}]:"${escapeQueryValue(v)}"`).join(" OR ");
  const cfg = baseCfg("Project");
  await searchAll("Project", {
    query: `${cfg.query} AND (${who})`,
    refine: cfg.refine,
    predicates: [...LABEL_FIELDS, "resourceid", PROJECT_SCOPE.predicate],
    onPage: (rows) =>
      rows.forEach((r) => {
        const name = labelOf(r);
        if (name && !into.has(name)) into.set(name, { name, id: firstValue(r, "resourceid") });
      }),
  });
}

async function loadAssignedProjects() {
  const ids = identityOf();
  if (!ids.length) throw Object.assign(new Error("NO_USER"), { code: "NO_USER" });
  const found = new Map();
  await addProjectsNamed(await memberProjectNames(), found);
  if (PROJECT_SCOPE.includeOwned) await addOwnedProjects(ids, found);
  return [...found.values()].sort((a, b) => a.name.localeCompare(b.name));
}

export default {
  loadDetails,

  // onNames(newNames) is called after every page; also returns the full sorted list
  async fetchProjects(onNames) {
    const seen = new Set();
    await searchAll("Project", {
      ...baseCfg("Project"),
      predicates: LABEL_FIELDS,
      onPage: (rows) => {
        const names = rows.map(labelOf).filter((n) => n && !seen.has(n) && seen.add(n));
        if (names.length) onNames?.(names);
      },
    });
    return [...seen].sort((a, b) => a.localeCompare(b));
  },

  // one project, with dates; onRows(rows) is called as results arrive
  async fetchTasks(projectName, onRows, onTotal) {
    const groups = await Promise.all(
      SCHEDULE_TYPES.map(async (t) => {
        const found = await findByType(projectName, t);
        onTotal?.(found.length); // known before the detail calls start
        return loadDetails(
          found.map((r) => lightRow(r, t)),
          onRows,
        );
      }),
    );
    return groups.flat();
  },

  // ---- projects assigned to the current user (FR-16, FR-17, FR-20) ----
  // Used by both "Single project" (the project list) and "All projects".
  // Assigned = the user is a member (listed on the user's Person object) or owns the
  // project (PROJECT_SCOPE.predicate). Never falls back to "every visible project".
  // The result is kept for a few minutes per user + security context; force reloads it.
  async fetchAssignedProjects({ force = false } = {}) {
    const key = useDashboardStore().cacheScope;
    if (!force && assignedMemo && assignedMemo.key === key && Date.now() - assignedMemo.at < ASSIGNED_TTL) {
      return assignedMemo.promise;
    }
    const promise = loadAssignedProjects();
    assignedMemo = { key, at: Date.now(), promise };
    promise.catch(() => {
      if (assignedMemo?.promise === promise) assignedMemo = null; // never keep a failure
    });
    return promise;
  },

  // Tasks of the given projects only, WITHOUT dates (dates load per page with loadDetails).
  // Every row carries its project name. To keep the number of searches low (the search
  // service answers 429 Too Many Requests when it gets too many), projects are read in
  // groups: one search per work type for up to PROJECT_SCOPE.taskChunk projects. A project
  // the group search returns nothing for is read on its own, as before. A failing project
  // is reported and the others still load.
  // callbacks: onRows(rows), onTotal(n), onProject({ name, ok, count })
  async listTasksOfProjects(projects, { onRows, onTotal, onProject } = {}) {
    const failed = [];
    const report = (name, rows) => {
      onTotal?.(rows.length);
      onRows?.(rows);
      onProject?.({ name, ok: true, count: rows.length });
    };
    const alone = [];
    for (let i = 0; i < projects.length; i += PROJECT_SCOPE.taskChunk) {
      const group = projects.slice(i, i + PROJECT_SCOPE.taskChunk);
      let byProject;
      try {
        byProject = await tasksOfProjectGroup(group.map((p) => p.name));
      } catch (e) {
        alone.push(...group); // the group search failed: read these projects one by one
        continue;
      }
      group.forEach((p) => {
        const rows = byProject.get(p.name) || [];
        if (rows.length) report(p.name, rows);
        else alone.push(p); // nothing found in the group search: confirm with the project's own search
      });
    }
    const readAlone = async (p) => {
      const groups = [];
      for (const t of SCHEDULE_TYPES) {
        groups.push(
          (await findByType(p.name, t))
            // keep only items that really belong to this eligible project (traceability)
            .filter((r) => allValues(r, USED_IN_PROJECT).map(String).includes(p.name))
            .map((r) => ({ ...lightRow(r, t), project: p.name })),
        );
      }
      report(p.name, groups.flat().filter((r) => r.id));
    };
    const again = [];
    await mapLimit(alone, PROJECT_SCOPE.concurrency, async (p) => {
      try {
        await readAlone(p);
      } catch (e) {
        again.push(p);
      }
    });
    // Second try for the projects that failed (usually "too many requests"): one at a time,
    // after a pause, before they are reported as not loaded.
    if (again.length) await http.sleep(PROJECT_SCOPE.retryPauseMs);
    for (const p of again) {
      try {
        await readAlone(p);
      } catch (e) {
        failed.push(p.name);
        onProject?.({ name: p.name, ok: false, count: 0 });
      }
    }
    return { failed };
  },
};
