// Sharing adapter for services/sharingApi.js, built on the 3DSpace ownership services
// used by the native 3DEXPERIENCE "Share" command (see SHARING in platformConfig.js).
// Only the current user's session is used: no tokens or cookies are handled here.

import http from "./httpClient.js";
import initApp from "@/utils/initApp";
import { SHARING } from "@/config/platformConfig";
import { ApiError, ERROR_CODES } from "./apiError";
import { ERROR_TEXT } from "@/utils/uiText";

const arr = (v) => (Array.isArray(v) ? v : []);
const str = (v) => (typeof v === "string" ? v : "");

// The Share services expect this header (sent by the native app on every call).
const headers = () => ({
  SecurityContext: initApp.getCTX(),
  "X-Requested-With": "XMLHttpRequest, csrf protection",
});

const withTenant = (path) => {
  const tenant = initApp.store().getServer;
  return tenant ? `${path}?tenant=${encodeURIComponent(tenant)}` : path;
};

const post = (path, body) => http.post(withTenant(path), body, { headers: headers() });

// The update service answers HTTP 200 with { success: false } when it refuses a change.
function confirmed(json, fallback) {
  if (json && json.success === true) return json;
  throw new ApiError(ERROR_CODES.SERVER, {
    message: fallback,
    detail: JSON.stringify(json || {}).slice(0, 500),
  });
}

const LABELS = new Map(SHARING.levels.map((l, i) => [l.value, { label: l.label, rank: i }]));

export const personIdOf = (p) => str(p?.personId) || (str(p?.login) ? p.login + SHARING.personIdSuffix : "");

export const loginOf = (personID) => {
  const id = str(personID);
  const sfx = SHARING.personIdSuffix;
  return sfx && id.toLowerCase().endsWith(sfx.toLowerCase()) ? id.slice(0, -sfx.length) : id;
};

function ownershipEntry(operation, person, logical) {
  const p = { personID: personIdOf(person) };
  if (!p.personID) throw new ApiError(ERROR_CODES.INVALID, { message: "This person can't be identified on the platform." });
  if (operation === "ADD") {
    if (person.firstName) p.personFirstName = person.firstName;
    if (person.lastName) p.personLastName = person.lastName;
    if (person.name) p.personFullName = person.name;
  }
  const entry = { operation, owner: { person: p, comment: "-" }, access: { logical } };
  if (operation === "REMOVE") entry.inheritedPath = [];
  return entry;
}

async function update(docId, ownership, fallback) {
  const json = await post(SHARING.update, { ownershipVector: [{ objectID: docId, ownership }] });
  return confirmed(json, fallback);
}

// Pure mappers (exported for tests).
export function mapGrantees(json, docId) {
  const vec = arr(json?.ownershipVector).find((v) => v.objectID === docId) || arr(json?.ownershipVector)[0];
  return arr(vec?.ownership)
    .filter((o) => o?.owner?.person?.personID && o?.access?.logical && o.access.logical !== SHARING.noAccess)
    .map((o) => {
      const p = o.owner.person;
      const name = str(p.personFullName) || [p.personFirstName, p.personLastName].filter(Boolean).join(" ");
      return {
        id: p.personID,
        personId: p.personID,
        login: loginOf(p.personID),
        name: name.split("\n")[0].trim(),
        firstName: str(p.personFirstName),
        lastName: str(p.personLastName),
        level: o.access.logical,
        inherited: arr(o.inheritedPath).length > 0,
      };
    });
}

export function mapLevels(json, docId) {
  const list = arr(json?.accessList).find((a) => a.objectID === docId) || arr(json?.accessList)[0];
  const levels = arr(list?.access)
    .filter((a) => str(a.logical) && a.logical !== SHARING.noAccess)
    .map((a) => ({ value: a.logical, label: str(a.nls) || LABELS.get(a.logical)?.label || a.logical }));
  const rank = (v) => LABELS.get(v)?.rank ?? 99;
  return levels.sort((a, b) => rank(a.value) - rank(b.value));
}

export function mapCanShare(json, docId) {
  const bo = arr(json?.boAccessRights).find((b) => b.objectID === docId) || arr(json?.boAccessRights)[0];
  const right = arr(bo?.accessRight).find((r) => r?.access?.physical === SHARING.shareRight);
  return json?.success === true && right?.right === true;
}

export default {
  async listGrantees(docId) {
    const json = await post(SHARING.ownership, { businessObject: [{ objectID: docId }] });
    if (json && json.success === false) confirmed(json, ERROR_TEXT.loadAccess);
    return mapGrantees(json, docId);
  },

  async listLevels(docId) {
    const json = await post(SHARING.logicalAccess, { businessObject: [{ objectID: docId }] });
    const levels = mapLevels(json, docId);
    return levels.length ? levels : SHARING.levels;
  },

  async canShare(docId) {
    try {
      const json = await post(SHARING.checkAccess, {
        boAccessRights: [{ objectID: docId, accessRight: [{ access: { physical: SHARING.shareRight } }] }],
      });
      return mapCanShare(json, docId);
    } catch (e) {
      return false;
    }
  },

  async grant(docId, people, level) {
    const list = arr(people);
    if (!list.length) return;
    await update(docId, list.map((p) => ownershipEntry("ADD", p, level)), ERROR_TEXT.share);
  },

  // The native Share panel changes a level by re-adding the person with the new level.
  async changeLevel(docId, grantee, level) {
    await update(docId, [ownershipEntry("ADD", grantee, level)], ERROR_TEXT.changeAccess);
  },

  async revoke(docId, grantee) {
    await update(docId, [ownershipEntry("REMOVE", grantee, SHARING.noAccess)], ERROR_TEXT.removeAccess);
  },
};
